"/**
 * @brief Register preconditions for OTA.
 */
void OTAUpdateManager::registerPreconditions(IPreconditionRegistry& reg) {
    reg.add("OTA Signature", PreconditionRole::Operational,
        [](void* ctx) -> PreconditionStatus {
            auto* self = static_cast<OTAUpdateManager*>(ctx);
            if (self->_config == nullptr) return {true, Cause::Met};
#ifdef OTA_ALLOW_UNSIGNED
            if (self->_config->otaPublicKey == nullptr) {
                // Return FallbackEngaged so it appears as a Degraded severity warning
                return {false, Cause::FallbackEngaged};
            }
#endif
            return {true, Cause::Met};
        },
        [](Cause cause, char* buf, size_t len, void* ctx) {
            snprintf(buf, len, "⚠️ OTA signature verification disabled.");
        },
        this);
}

